import React from "react";

export default function Home() {
  return (
    <div className="text-center mt-10">
      <h1 className="text-3xl font-bold text-blue-600">Welcome to AI Interview Coach</h1>
      <p className="mt-4 text-lg text-gray-600">
        Prepare smarter with AI-driven mock interviews and personalized feedback.
      </p>
    </div>
  );
}
